from textual.app import App, ComposeResult
from textual.containers import Container
from textual.message import Message
from textual.widgets import Button, Static


class MyWidget(Static):
    """A widget with a custom message."""

    class ButtonPressed(Message):
        """Posted when the button is pressed."""

        def __init__(self, button_id: str) -> None:
            super().__init__()
            self.button_id = button_id

    def compose(self) -> ComposeResult:
        yield Button("Click Me!", id="my_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "my_button":
            self.post_message(self.ButtonPressed(button_id="my_button"))


class ParentWidget(Container):
    """Parent container that receives messages from MyWidget."""

    def compose(self) -> ComposeResult:
        yield MyWidget()

    def on_my_widget_button_pressed(self, message: MyWidget.ButtonPressed) -> None:
        self.notify(f"Received: {message.button_id}")


class MyApp(App):
    """Main application."""

    def compose(self) -> ComposeResult:
        yield ParentWidget()


if __name__ == "__main__":
    app = MyApp()
    app.run()

